import Phaser from 'phaser';
import { preloadAssets, setupAssets } from '../assets';
import { Title } from './Title';
import { Room } from './Room';

export class Boot extends Phaser.Scene {
  constructor() {
    super('boot');
  }

  preload() {
    preloadAssets(this);
  }

