override update(_time: number, delta: number) {
  if (this.frozen) return;
  // A paused room does not run: Joe, the creatures and the clocks all wait for the player.
  if (this.paused) return;
  const dt = Math.min(delta / 1000, 1 / 20);
  const k = this.keys;
  const input = {
    left: k.left.isDown || k.a.isDown,
    right: k.right.isDown || k.d.isDown,
    up: k.up.isDown || k.w.isDown,
    down: k.down.isDown,
    jump: Phaser.Input.Keyboard.JustDown(k.space) || Phaser.Input.Keyboard.JustDown(k.up) || Phaser.Input.Keyboard.JustDown(k.w),
  };
  if (!this.busy && !this.joe.dead) this.joe.update(input, dt, this.world, GRAVITY);
  else this.joe.update(input, dt, this.world, GRAVITY);
  this.updateCreatures(dt);
  this.updateCrumbles(dt);
  this.updatePickups();
  this.updateDoors();
  this.updateDarkness();
  this.updateBonus(dt);

  if (this.joe.mover.y > HEIGHT + 48 && !this.joe.dead) this.joe.kill();
  if (this.joe.dead && !this.busy) {
    this.busy = true;
    this.cameras.main.shake(240, 0.012);
    sfx.death();
    this.time.delayedCall(1600, () => this.afterDeath());
  }
}

private updateCreatures(dt: number) {
  for (const c of this.creatures) {
    if (c.dead || c.spent) continue;
    const m = c.mover;
    m.vx = c.dir * (c.kind === 'skull' ? 46 : 42);
    if (c.kind === 'skull') {
      // The skull hops at Joe when he comes into reach.
      const sameRow = Math.abs((this.joe.mover.y - 22 - m.y) / TILE) < 1.6;
      if (sameRow && Math.abs(this.joe.mover.x - m.x) < TILE * 3 && m.onGround) m.vy = -430;

input.newString:
this.time.delayedCall(1600, () => this.afterDeath());
    }
  }

  /**
   * P pauses the room and P again starts it up. While the game is paused nothing moves: Joe, the creatures and
   * the timers all stop, and PAUSED stands in the middle of the screen.
   */
  private togglePause() {
    this.paused = !this.paused;
    if (this.paused) {
      // The clock holds the timers, the tweens and the animations hold the picture of it all.
      this.time.paused = true;
      this.tweens.pauseAll();
      this.anims.pauseAll();
      this.pausedText = this.add
        .text(WIDTH / 2, HEIGHT / 2, 'PAUSED', { ...HUD_TEXT, fontSize: '10px', stroke: '#000000', strokeThickness: 5 })
        .setOrigin(0.5)
        .setDepth(960)
        .setResolution(2);
      return;
    }
    this.time.paused = false;
    this.tweens.resumeAll();
    this.anims.resumeAll();
    this.pausedText?.destroy();
    this.pausedText = null;
  }

